const event = $json.event || 'order.status';
const data = $json.data || {};
const orderNumber = data.orderNumber || data.order_number || $json.orderNumber || $json.order_number || 'UNKNOWN';
const customerEmail = data.customerEmail || data.customer_email || $json.customerEmail || $json.customer_email || '';
const customerName = data.customerName || data.customer_name || $json.customerName || $json.customer_name || 'Customer';
const status = (data.status || $json.status || '').toUpperCase();
const total = data.total || $json.total || 0;
const deliveryLocation = data.deliveryLocation || data.delivery_location || $json.deliveryLocation || $json.delivery_location || '';
const supportEmail = 'support@smartbestbrands.com';

let subject = `Smart Best Brands Order ${orderNumber} Update`;
let html = `<p>Hi ${customerName},</p>`;

if (event === 'order.created') {
  subject = `Order ${orderNumber} received`;
  html += `<p>We have received your order <strong>${orderNumber}</strong> successfully.</p>`;
  html += `<p><strong>Total amount:</strong> ₦${Number(total).toLocaleString()}</p>`;
  html += `<p>We will notify you again when payment is confirmed and your order moves to the next stage.</p>`;
} else if (event === 'order.paid') {
  subject = `Payment confirmed for order ${orderNumber}`;
  html += `<p>Your payment for order <strong>${orderNumber}</strong> has been confirmed.</p>`;
  html += `<p><strong>Total paid:</strong> ₦${Number(total).toLocaleString()}</p>`;
  html += `<p>We are now processing your order.</p>`;
} else if (event === 'order.status') {
  subject = `Order ${orderNumber} status updated`;
  html += `<p>Your order <strong>${orderNumber}</strong> status has been updated to <strong>${status}</strong>.</p>`;
  if (deliveryLocation) {
    html += `<p><strong>Delivery location:</strong> ${deliveryLocation}</p>`;
  }
} else {
  subject = `Smart Best Brands update for order ${orderNumber}`;
  html += `<p>Your order <strong>${orderNumber}</strong> has a new update.</p>`;
}

html += `<p>If you have any questions, reply directly to this email or contact ${supportEmail}.</p>`;
html += `<p>Thank you for choosing Smart Best Brands.</p>`;

return [{
  json: {
    event,
    orderNumber,
    customerEmail,
    customerName,
    status,
    total,
    deliveryLocation,
    subject,
    html,
    groqQuery: '*[_type == "product"]{title,slug,price}'
  }
}];

const payload = $json;
const products = payload.body?.result ?? payload.body ?? [];
let html = payload.html || '';
if (Array.isArray(products) && products.length > 0) {
  html += '<hr/><h3>Featured Products</h3><ul>';
  for (const item of products) {
    const title = item.title || item.name || 'Product';
    const price = item.price != null ? `₦${Number(item.price).toLocaleString()}` : 'Price unavailable';
    html += `<li>${title} — ${price}</li>`;
  }
  html += '</ul>';
}
return [{ json: { customerEmail: payload.customerEmail, subject: payload.subject, html } }];
